};

// 地点转换函数
const 转换地点 = (地点) => {
  if (!地点 || typeof 地点 !== 'string') return '高中部教学楼';
  const trimmed = 地点.trim();
  if (!trimmed) return '高中部教学楼';
  if (有效地点.includes(trimmed)) return trimmed;
  if (地点映射[trimmed]) return 地点映射[trimmed];
  for (const 标准地点 of 有效地点) {
    if (trimmed.includes(标准地点) || 标准地点.includes(trimmed)) return 标准地点;
  }
  return trimmed;
};

