  班级: z.string().prefault('未知班级'),
  好感度: z.coerce.number().min(0).max(100).prefault(0),
  性格: z.string().prefault('未知'),
  当前心声: z.string().prefault('无'),
  当前行为: z.string().prefault('发呆'),
  喜欢的人: z.string().prefault('无'),
  当前所在地: z.string().transform(转换地点).describe('必须是地图中的建筑名称').prefault('高中部教学楼'),
  今日穿搭: 穿搭Schema.prefault({}),
  容貌特征: 容貌特征Schema.prefault({}),
  身体数据: 身体数据Schema.prefault({}),
  隐私档案: 隐私档案Schema.prefault({}),
  经验档案: 经验档案Schema.prefault({}),
});

// 校规内容结构
const 校规内容Schema = z.object({
  内容: z.string().prefault(''),
  开关: z.boolean().prefault(true),
});

// 活动内容结构
const 活动内容Schema = z.object({
  活动地点: z.string().prefault(''),
  活动开启时间: z.string().prefault(''),
  活动结束时间: z.string().prefault(''),
});

// 建筑类型枚举
const 建筑类型枚举 = z.enum(['learning', 'dorm', 'food', 'sports', 'nature', 'custom']).prefault('custom');

// 建筑大小枚举
const 建筑大小枚举 = z.enum(['巨型', '大型', '中型', '小型', '迷你']).prefault('中型');

// 建筑结构
const 建筑Schema = z.object({
  类型: 建筑类型枚举,
  大小: 建筑大小枚举,
  描述: z.string().prefault(''),
  坐标X: z.coerce.number().min(-50).max(150).prefault(50),
  坐标Y: z.coerce.number().min(-50).max(100).prefault(50),
  启用: z.boolean().prefault(true),
});

// 主 Schema
export const Schema = z.object({
  // 时间系统
  时间: z
    .object({
      年: z.coerce.number().prefault(2024),
      月: z.coerce.number().min(1).max(12).prefault(9),
      日: z.coerce.number().min(1).max(31).prefault(1),
      小时: z.coerce.number().min(0).max(23).prefault(7),
      分钟: z.coerce.number().min(0).max(59).prefault(0),
    })
    .prefault({}),

  // 玩家信息
  玩家: z
    .object({
      姓名: z.string().prefault('我是谁'),
      身份: z.string().prefault('学生'),
      班级: z.string().prefault('高一(2)班'),
      年龄: z.coerce.number().prefault(16),
      当前所在地: z.string().transform(转换地点).prefault('学校大门'),
      当前穿搭: 穿搭Schema.prefault({}),
    })
    .prefault({}),

  // 角色列表：支持动态添加角色（关键修改：使用 z.record）
  角色: z.record(z.string(), 角色档案Schema).prefault({}),

  // 校规列表
  校规: z.record(z.string(), 校规内容Schema).prefault({}),

  // 活动列表
  活动: z.record(z.string(), 活动内容Schema).prefault({}),

  // 地图建筑
  地图: z
    .object({
      建筑: z.record(z.string(), 建筑Schema).prefault({}),
    })
    .prefault({}),
});

// 注册 MVU Schema
$(() => {
  registerMvuSchema(Schema);
});
